import numpy as np

class ModulatedSineWaves:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Ensure input is within bounds [-5, 5]
        x = np.clip(x, -5.0, 5.0)
        # Each dimension has a sine wave with increasing frequency
        frequencies = np.arange(1, self.dim + 1)
        # Modulate the sine waves to ensure homogeneous basin sizes
        modulated = np.sin(frequencies * np.pi * x) * (1 + 0.1 * frequencies)
        return np.sum(modulated**2)
